package com.jbrempresa.backend.entity;
import java.time.LocalDateTime; import com.fasterxml.jackson.annotation.JsonFormat; import jakarta.persistence.*;
@Entity @Table(name="personas_contactos_canal") public class PersonaContactoCanal {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="pcc_id") private Long pccId; @Column(name="emp_id",nullable=false) private Long empId; @Column(name="coc_id",nullable=false) private Long cocId; @Column(name="per_id",nullable=false) private Long perId; @Column(name="pcc_tip",nullable=false,length=20) private String pccTip; @Column(name="pcc_usu_mov",nullable=false,length=50) private String pccUsuMov; @JsonFormat(pattern="dd/MM/yyyy HH:mm:ss") @Column(name="pcc_fec_mov",nullable=false) private LocalDateTime pccFecMov; @Column(name="pcc_act",nullable=false) private Boolean pccAct;
 public Long getPccId(){return pccId;}public void setPccId(Long v){pccId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getCocId(){return cocId;}public void setCocId(Long v){cocId=v;}public Long getPerId(){return perId;}public void setPerId(Long v){perId=v;}public String getPccTip(){return pccTip;}public void setPccTip(String v){pccTip=v;}public String getPccUsuMov(){return pccUsuMov;}public void setPccUsuMov(String v){pccUsuMov=v;}public LocalDateTime getPccFecMov(){return pccFecMov;}public void setPccFecMov(LocalDateTime v){pccFecMov=v;}public Boolean getPccAct(){return pccAct;}public void setPccAct(Boolean v){pccAct=v;}
}
